import { webManifest } from "#shared/site";
import { TEXTS } from "#shared/texts";

// Web app manifest of the English version (start_url /en/). The German one is generated by @vite-pwa/nuxt.
export default defineEventHandler((event) => {
  setHeader(event, "content-type", "application/manifest+json");
  return JSON.stringify(webManifest(TEXTS.en));
});
